import com.google.gson.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import java.util.jar.*;
import java.util.zip.*;
/** Static symbolic-member existence/access checks; no class definition or initialization.
 * Lookup order follows JVMS17 5.4.3.2-4. Dynamic bootstrap execution is out of scope.
 */
public final class RuntimeMemberClosure implements Opcodes{
 record Target(String owner,int access){}
 static Map<String,ClassNode>headers=new HashMap<>(),owned=new TreeMap<>();static List<JarFile>providers=new ArrayList<>();static Map<String,JarFile>providerByName=new HashMap<>();static Set<String>missing=new TreeSet<>();static JsonArray failures=new JsonArray();static int methodSites,fieldSites,handleSites,polymorphic,arrayClones;
 static ClassNode header(String name)throws Exception{if(headers.containsKey(name))return headers.get(name);if(name.startsWith("["))return header("java/lang/Object");URL resource=ClassLoader.getPlatformClassLoader().getResource(name+".class");byte[]bytes=null;if(resource!=null&&resource.getProtocol().equals("jrt")){try(var in=resource.openStream()){bytes=in.readAllBytes();}}else{JarFile jar=providerByName.get(name);if(jar!=null){var e=jar.getJarEntry(name+".class");if(e!=null)try(var in=jar.getInputStream(e)){bytes=in.readAllBytes();}}if(bytes==null)for(var p:providers){var e=p.getJarEntry(name+".class");if(e!=null){try(var in=p.getInputStream(e)){bytes=in.readAllBytes();}break;}}}if(bytes==null){missing.add(name);headers.put(name,null);return null;}ClassNode c=new ClassNode();new ClassReader(bytes).accept(c,ClassReader.SKIP_CODE|ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);if(!c.name.equals(name))throw new IllegalArgumentException("Header identity mismatch");headers.put(name,c);return c;}
 static Target field(String owner,String name,String desc,Set<String>seen)throws Exception{if(owner==null||!seen.add(owner))return null;var c=header(owner);if(c==null)return null;for(var f:c.fields)if(f.name.equals(name)&&f.desc.equals(desc))return new Target(owner,f.access);for(String i:c.interfaces){var r=field(i,name,desc,seen);if(r!=null)return r;}return field(c.superName,name,desc,seen);}
 static Target method(String owner,String name,String desc,Set<String>seen)throws Exception{if(owner==null||!seen.add(owner))return null;var c=header(owner);if(c==null)return null;for(var m:c.methods)if(m.name.equals(name)&&m.desc.equals(desc))return new Target(owner,m.access);if(name.equals("<init>"))return null;if(Set.of("java/lang/invoke/MethodHandle","java/lang/invoke/VarHandle").contains(owner))for(var m:c.methods)if(m.name.equals(name)&&(m.access&(ACC_NATIVE|ACC_VARARGS))==(ACC_NATIVE|ACC_VARARGS)){polymorphic++;return new Target(owner,m.access);}if((c.access&ACC_INTERFACE)!=0){var object=header("java/lang/Object");for(var m:object.methods)if(m.name.equals(name)&&m.desc.equals(desc)&&(m.access&(ACC_PUBLIC|ACC_STATIC))==ACC_PUBLIC)return new Target(object.name,m.access);}else{var r=method(c.superName,name,desc,seen);if(r!=null)return r;}for(String i:c.interfaces){var r=method(i,name,desc,seen);if(r!=null&&(r.access()&(ACC_PRIVATE|ACC_STATIC))==0)return r;}return null;}
 static String pkg(String o){int n=o.lastIndexOf('/');return n<0?"":o.substring(0,n);}
 static boolean subtype(String child,String parent,Set<String>seen)throws Exception{if(Objects.equals(child,parent))return true;if(child==null||!seen.add(child))return false;var c=header(child);if(c==null)return false;if(subtype(c.superName,parent,seen))return true;for(String i:c.interfaces)if(subtype(i,parent,seen))return true;return false;}
 static String nest(String owner)throws Exception{var c=header(owner);return c==null?owner:c.nestHostClass==null?owner:c.nestHostClass;}
 static boolean nestmate(String a,String b)throws Exception{if(a.equals(b))return true;String host=nest(a);if(!host.equals(nest(b))||!pkg(a).equals(pkg(b)))return false;var h=header(host);return h!=null&&(a.equals(host)||h.nestMembers!=null&&h.nestMembers.contains(a))&&(b.equals(host)||h.nestMembers!=null&&h.nestMembers.contains(b));}
 static boolean accessible(String caller,Target target)throws Exception{return(target.access()&ACC_PUBLIC)!=0||(target.access()&ACC_PRIVATE)!=0&&nestmate(caller,target.owner())||(target.access()&ACC_PRIVATE)==0&&(pkg(caller).equals(pkg(target.owner()))||(target.access()&ACC_PROTECTED)!=0&&subtype(caller,target.owner(),new HashSet<>()));}
 static void fail(String caller,String callerMethod,String owner,String name,String desc,String reason){JsonObject r=new JsonObject();r.addProperty("caller",caller);r.addProperty("caller_method",callerMethod);r.addProperty("target_owner",owner);r.addProperty("name",name);r.addProperty("descriptor",desc);r.addProperty("reason",reason);failures.add(r);}
 static void check(String caller,String cm,String owner,String name,String desc,boolean isField,boolean isStatic,boolean itf)throws Exception{if(owner.startsWith("[")&&!isField&&name.equals("clone")&&desc.equals("()Ljava/lang/Object;")){arrayClones++;return;}var c=header(owner);if(c==null){fail(caller,cm,owner,name,desc,"missing_symbolic_owner");return;}if((c.access&ACC_PUBLIC)==0&&!pkg(caller).equals(pkg(owner)))fail(caller,cm,owner,name,desc,"inaccessible_symbolic_owner");if(!isField&&((c.access&ACC_INTERFACE)!=0)!=itf){fail(caller,cm,owner,name,desc,"method_class_interface_tag_mismatch");return;}Target t=isField?field(owner,name,desc,new HashSet<>()):method(owner,name,desc,new HashSet<>());if(t==null){fail(caller,cm,owner,name,desc,"missing_"+(isField?"field":"method"));return;}if(((t.access()&ACC_STATIC)!=0)!=isStatic)fail(caller,cm,owner,name,desc,"static_instance_kind_mismatch");if(!accessible(caller,t))fail(caller,cm,owner,name,desc,"inaccessible_resolved_member");}
 static void handle(String caller,String cm,Object v)throws Exception{if(v instanceof Handle h){handleSites++;int tag=h.getTag();check(caller,cm,h.getOwner(),h.getName(),h.getDesc(),tag<=H_PUTSTATIC,tag==H_GETSTATIC||tag==H_PUTSTATIC||tag==H_INVOKESTATIC,h.isInterface());}else if(v instanceof ConstantDynamic c){handle(caller,cm,c.getBootstrapMethod());for(int i=0;i<c.getBootstrapMethodArgumentCount();i++)handle(caller,cm,c.getBootstrapMethodArgument(i));}}
 public static void main(String[]a)throws Exception{try(var z=new ZipFile(a[0])){for(var es=z.entries();es.hasMoreElements();){var e=es.nextElement();if(e.isDirectory()||!e.getName().endsWith(".class"))continue;ClassNode c=new ClassNode();try(var in=z.getInputStream(e)){new ClassReader(in.readAllBytes()).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);}if(owned.put(c.name,c)!=null)throw new IllegalArgumentException("Duplicate owned class");headers.put(c.name,c);}}
  for(int i=2;i<a.length;i++){JarFile jar=new JarFile(Path.of(a[i]).toFile(),false,ZipFile.OPEN_READ,Runtime.version());providers.add(jar);for(var es=jar.entries();es.hasMoreElements();){var e=es.nextElement();if(e.getName().endsWith(".class")&&!e.getName().startsWith("META-INF/"))providerByName.putIfAbsent(e.getName().substring(0,e.getName().length()-6),jar);}}
  for(var c:owned.values())for(var m:c.methods){String cm=m.name+m.desc;for(var n:m.instructions){if(n instanceof MethodInsnNode v){methodSites++;check(c.name,cm,v.owner,v.name,v.desc,false,v.getOpcode()==INVOKESTATIC,v.itf);}else if(n instanceof FieldInsnNode v){fieldSites++;check(c.name,cm,v.owner,v.name,v.desc,true,v.getOpcode()==GETSTATIC||v.getOpcode()==PUTSTATIC,false);}else if(n instanceof LdcInsnNode v)handle(c.name,cm,v.cst);else if(n instanceof InvokeDynamicInsnNode v){handle(c.name,cm,v.bsm);for(Object b:v.bsmArgs)handle(c.name,cm,b);}}}
  JsonObject out=new JsonObject();out.addProperty("status",failures.isEmpty()?"passed_static_owned_member_reference_existence_kind_access":"failed_static_owned_member_reference_audit");out.addProperty("owned_classes",owned.size());out.addProperty("method_instruction_sites",methodSites);out.addProperty("field_instruction_sites",fieldSites);out.addProperty("method_handle_sites",handleSites);out.addProperty("signature_polymorphic_matches",polymorphic);out.addProperty("array_clone_matches",arrayClones);out.addProperty("failure_count",failures.size());out.add("failures",failures);out.add("unresolved_header_types",new Gson().toJsonTree(missing));out.addProperty("client_classes_defined",0);out.addProperty("client_initialized",false);out.addProperty("scope","Static member existence, class/interface tags, staticness and declared access/nest checks. Does not prove dynamic invocation selection, protected receiver values, arbitrary bootstrap execution or business behavior.");Files.writeString(Path.of(a[1]),new GsonBuilder().setPrettyPrinting().create().toJson(out),StandardOpenOption.CREATE_NEW);for(var p:providers)p.close();System.out.println("methods="+methodSites+" fields="+fieldSites+" handles="+handleSites+" failures="+failures.size());if(!failures.isEmpty()||!missing.isEmpty())System.exit(2);
 }
}
